changeSet.sql:
CREATE OR REPLACE FUNCTION modeling_reject_release_candidate_command_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'MODEL_RELEASE_CANDIDATE_COMMAND_APPEND_ONLY'
        USING ERRCODE = '55000';
END;
$function$;

rollback.sql:
DO $$
BEGIN
    LOCK TABLE modeling_model_release_candidate_command IN ACCESS EXCLUSIVE MODE;
    IF EXISTS (SELECT 1 FROM modeling_model_release_candidate_command) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_MODEL_RELEASE_CANDIDATE_COMMAND_DATA_EXISTS';
    END IF;
END $$;
